uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// User Parameters
uniform float u_speed;
uniform float u_scale;
uniform float u_sparkle;
uniform float u_glow;
uniform float u_hue;   
uniform float u_hue2;  

// AI Aesthetic Parameters
uniform float u_neuro_complexity; 
uniform float u_chromatic_aberration; 
uniform float u_bass; 
uniform float u_glitch_intensity; 

// "Mad" Parameters
uniform float u_rage_intensity; 
uniform float u_distortion_warp; 

// Stretchy Blob Parameters
uniform float u_stretch_amount;
uniform float u_blob_viscosity;

// New Smoothness Parameter
uniform float u_smoothness;

// Ethereal Green/Ghostly Parameters
uniform float u_metallic;
uniform float u_ethereal_mist;
uniform float u_sunset_bloom; // Renamed label in UI to Ethereal Bloom

out vec4 fragColor;

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float hash(float n) {
    return fract(sin(n) * 43758.5453123);
}

// Seamless FBM using a noise function that doesn't rely on mod(iTime) directly
float fbm(vec2 p, float rage, float bassParam, float time) {
    float v = 0.0;
    float a = 0.5;
    vec2 shift = vec2(100.0);
    for (int i = 0; i < 4; ++i) {
        v += a * (sin(p.x + time * 0.1) + cos(p.y - time * 0.1));
        p = rot(0.5 + rage * 0.2) * p * (1.8 + bassParam * 0.5) + shift;
        a *= 0.5;
    }
    return v;
}

vec3 hsb2rgb(vec3 c) {
    // Smoothed HSB to RGB to prevent banding during fast hue shifts
    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    rgb = rgb * rgb * (3.0 - 2.0 * rgb);
    return c.z * mix(vec3(1.0), rgb, c.y);
}

void main() {
    // --- SETTINGS FIXED TO YOUR PARAMS ---
    float speed = (u_speed <= 0.001) ? 0.0 : u_speed * 0.1; 
    float scale = (u_scale <= 0.1) ? 0.9 : u_scale;
    float sparkleInt = u_sparkle; 
    float glowInt = u_glow;

    // Default hue shifts toward Greens and Teals (0.3 - 0.5)
    float hue1 = u_hue;
    float hue2 = u_hue2;

    float neuro = u_neuro_complexity; 
    float caParam = u_chromatic_aberration;
    float bass = (u_bass > 0.0) ? u_bass : 0.0;
    float glitch = u_glitch_intensity;
    float rage = u_rage_intensity;
    float warp = u_distortion_warp;

    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    float time = iTime * speed;

    // Apply "Stretchy" blooming effect to UVs over time
    float stretchCycle = sin(time * 0.5) * 0.5 + 0.5;
    float stretchFactor = 1.0 + stretchCycle * u_stretch_amount;
    uv *= mix(1.0, 1.0 / stretchFactor, length(uv) * u_blob_viscosity);

    // Smooth Shake
    if (rage > 0.01) {
        vec2 shake = vec2(sin(iTime * 20.0), cos(iTime * 17.0)) * rage * 0.005;
        uv += shake;
    }

    // Glitch logic
    if (glitch > 0.01) {
        float sliceY = floor(uv.y * 20.0);
        float glitchChance = fract(sin(sliceY * 12.9898) * 43758.5453);
        if (glitchChance > 0.98 - glitch * 0.05) {
            uv.x += (sin(iTime * 50.0 + sliceY) * 0.02) * glitch;
        }
    }

    // Fluid background
    float fluid = fbm(uv * (2.0 + warp) - time * 0.2, rage, bass, time) * (neuro + rage);
    uv += fluid * (0.05 + warp * 0.05 + stretchCycle * 0.1);

    // Ethereal Background Theme: Deep forest greens and midnight teals
    vec3 forestBase = vec3(0.01, 0.05, 0.03); // Deep emerald-dark base
    vec3 bgCol = hsb2rgb(vec3(mix(hue1, hue2, 0.5), mix(0.7, 0.9, rage), 0.01 + max(fluid, 0.0) * 0.04));
    bgCol = mix(bgCol, forestBase, 0.7);
    vec3 finalColor = bgCol;

    const int LAYERS = 12;

    for (int i = 0; i < LAYERS; i++) {
        float fi = float(i);
        float progress = fi / float(LAYERS);
        float z = fract(progress - time * 0.1);

        float fade = smoothstep(0.0, 0.25 * u_smoothness, z) * smoothstep(1.0, 0.75 / u_smoothness, z);
        float layerScale = mix(20.0, 1.0, 1.0 - z) / (scale * mix(1.0, stretchFactor, 0.5));
        vec2 p = uv * layerScale;

        p *= rot(z * warp * 2.0 + time * 0.05 + fi);
        float stretchOsc = sin(time * 0.8 + fi) * u_stretch_amount * 0.2;
        p += vec2(sin(p.y * 0.5 + time * 0.5 + stretchOsc), cos(p.x * 0.5 - time * 0.5 - stretchOsc)) * (0.5 + stretchCycle);

        float ca = (caParam + rage * 0.5) * 0.2 * (1.0 - z);
        float dR = length(sin(p - ca));
        float dG = length(sin(p));
        float dB = length(sin(p + ca));

        float radius = 0.4 * (1.0 + bass * 0.8 + stretchCycle * 0.3);

        float coreR = smoothstep(radius + 0.1, radius - 0.1, dR);
        float coreG = smoothstep(radius + 0.1, radius - 0.1, dG);
        float coreB = smoothstep(radius + 0.1, radius - 0.1, dB);

        float glowSharpness = 8.0 / (glowInt + 0.001); 
        float glowR = exp(-abs(dR - radius) * glowSharpness) * glowInt;
        float glowG = exp(-abs(dG - radius) * glowSharpness) * glowInt * (1.0 + rage);
        float glowB = exp(-abs(dB - radius) * glowSharpness) * glowInt;

        float hueOsc = sin(time * 0.2 + progress * 6.283) * 0.5 + 0.5;
        float layerHue = mix(hue1, hue2, hueOsc);

        if (rage > 0.01) {
            float rageHueShift = sin(time * 1.5 + fi) * 0.1; 
            layerHue = mix(layerHue, 0.3 + rageHueShift, rage * 0.5); // Force shift towards bright lime during rage
        }

        // Ethereal palette: focus on Greens, Cyans, and ghost-whites
        vec3 col = hsb2rgb(vec3(layerHue, mix(0.6, 1.0, rage + bass), 1.0));

        // Metallic reflection logic: Ethereal silver/emerald
        float metal = pow(max(0.0, sin(p.x + p.y + time)), 4.0) * u_metallic;
        col = mix(col, vec3(0.7, 1.0, 0.85), metal); 

        vec3 layerColor = vec3(0.0);
        layerColor.r += col.r * (glowR * 0.4 + coreR * 0.1); // Muted red
        layerColor.g += col.g * (glowG + coreG * 0.5);     // Strong green
        layerColor.b += col.b * (glowB * 0.7 + coreB * 0.3); // Soft cyan/blue

        float sparkVal = max(0.0, sin(p.x * 8.0 + time * 0.5) * sin(p.y * 8.0 - time * 0.7));
        sparkVal = pow(sparkVal, 15.0) * sparkleInt * 8.0;

        // Minty/White sparkles
        vec3 sparkleCol = mix(vec3(0.8, 1.0, 0.9), col, 0.5);
        layerColor += sparkleCol * sparkVal * (glowG + 0.5); 

        finalColor += layerColor * fade * (1.5 - z);
    }

    // Add Ethereal Mist (Cool Forest Fog)
    float mist = fbm(uv0 * 2.5 + time * 0.1, 0.0, bass, time * 0.5);
    vec3 mistCol = mix(vec3(0.1, 1.0, 0.4), vec3(0.0, 0.8, 0.6), sin(time)*0.5+0.5);
    finalColor += mistCol * mist * u_ethereal_mist * 0.6;

    // Ethereal Bloom (Spirit-like glow)
    float bloom = exp(-length(uv0) * 1.5) * u_sunset_bloom;
    finalColor += vec3(0.4, 1.0, 0.7) * bloom;

    // Vignette - Deep Forest Tint
    finalColor *= (1.1 + rage * 0.4) - length(uv0) * (0.7 + rage * 0.5 + stretchCycle * 0.2);

    // Final clamp and atmosphere adjustment
    finalColor = pow(max(finalColor, 0.0), vec3(0.9 - rage * 0.2)); 

    // Tint the final shadows toward deep moss/seaweed green
    finalColor += vec3(0.02, 0.08, 0.05) * (1.0 - length(uv0));

    finalColor = smoothstep(-0.02, 1.1 + rage * 0.5 + stretchCycle * 0.1, finalColor);

    fragColor = vec4(finalColor, 1.0);
}
